#!/usr/bin/env python3
"""
CivicFix — District Government Edition One-Click Updater (upgrade_civicfix_gov.py)
Extracts and installs:
  - Official CivicFix Logo (loogo.jpeg) & Dandi March 1930 Upper Strip
  - 5-Page Government Portal UI (index.html, css/style.css)
  - WebRTC Live Camera Capture + Date/Time/GPS Evidence Stamp (js/app.js)
  - Street/Satellite GIS Map & Landmark Search (js/map.js)
  - 6-Department Auto-Routing & SLA Backend (php/*.php & python/*.py)
"""

import os
import zlib
import base64

TARGET_DIR = r"C:\xampp\htdocs\CivicFix"
if not os.path.isdir(TARGET_DIR):
    TARGET_DIR = os.getcwd()

BUNDLE = {
  "loogo.jpeg": "",
  "index.html": "",
  "css/style.css": "",
  "js/map.js": "",
  "js/app.js": "",
  "php/db.php": "",
  "php/python_client.php": "",
  "php/ai_preview.php": "",
  "php/submit_complaint.php": "",
  "php/list_complaints.php": "",
  "php/track_complaint.php": "",
  "php/complaint_details.php": "",
  "php/admin_login.php": "",
  "php/admin_logout.php": "",
  "php/update_status.php": "",
  "python/requirements.txt": "eNpzy0kszrazNdYz0DPgCk8tyq5KLU2H8QGDiwgu",
  "python/priority_engine.py": "",
  "python/duplicate_detector.py": "",
  "python/app.py": "",
  "database/schema.sql": "",
  "uploads/.htaccess": "eNpFzbEOwjAMBNA9X2EVBhiAARAMVUckBgRiZgmJRSylqUlcRKV8PMmEhzfd+WZwi/jBIJBMJBbAL5pRaAhAIZFFEIcwsh+0TWApopEhTurKNZNgdQ62VJJqT+QxXbQYB81jvWDHmZ30vsjbyq6yrxwqx4KOmUtgyuZFOblcPuWnluW86RSUu+N7LJOgvQeLgdCqdvMf6tQPm9dFvg==",
  ".gitignore": ""
}

def main():
    print(f"Upgrading CivicFix in: {TARGET_DIR}")
    for rel_path, compressed_b64 in BUNDLE.items():
        full_path = os.path.join(TARGET_DIR, rel_path.replace("/", os.sep))
        os.makedirs(os.path.dirname(full_path), exist_ok=True)
        raw_bytes = zlib.decompress(base64.b64decode(compressed_b64))
        with open(full_path, "wb") as f:
            f.write(raw_bytes)
        print(f"  [OK] Wrote {rel_path} ({len(raw_bytes)} bytes)")

    for sub in ["uploads/issues", "uploads/resolutions", "docs"]:
        os.makedirs(os.path.join(TARGET_DIR, sub.replace("/", os.sep)), exist_ok=True)

    print("\n============================================================")
    print(" SUCCESS! CivicFix District Government Edition is installed!")
    print(" Open in browser: http://localhost/CivicFix/ (Press Ctrl+F5)")
    print("============================================================")

if __name__ == "__main__":
    main()